import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api, { eur, formatApiErrorDetail } from "@/lib/api";
import { useCart } from "@/context/CartContext";
import { useAuth } from "@/context/AuthContext";
import { toast } from "sonner";
import { ShieldCheck, Truck, Mail, CreditCard } from "lucide-react";
import { usePageTitle } from "@/hooks/usePageTitle";
import { ConsentCheckbox } from "@/components/shop/ConsentCheckbox";
import { Link } from "react-router-dom";

export default function Checkout() {
  usePageTitle("Checkout");
  const { items, subtotal, weight, clear } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  const [options, setOptions] = useState([]);
  const [regions, setRegions] = useState([]);
  const [shipId, setShipId] = useState("standard");
  const [paymentMethod, setPaymentMethod] = useState("bank_transfer");
  const [cardEnabled, setCardEnabled] = useState(false);
  useEffect(() => {
    api.get("/payments/config").then(({ data }) => setCardEnabled(!!data.card_enabled)).catch(() => {});
  }, []);
  const [unloadingLabel, setUnloadingLabel] = useState("Consegna a piano strada");
  const [unloadingPrice, setUnloadingPrice] = useState(0);
  const [customerType, setCustomerType] = useState("privato"); // "privato" | "azienda"
  const [quote, setQuote] = useState({
    available: true, shipping_cost: 0, breakdown: [],
    vat_rate_products: 22, vat_rate_shipping: 22,
    vat_amount_products: 0, vat_amount_shipping: 0, vat_amount_total: 0,
  });
  const [busy, setBusy] = useState(false);
  const [okTerms, setOkTerms] = useState(false);
  const [okWithdrawal, setOkWithdrawal] = useState(false);
  const [error, setError] = useState("");

  const [form, setForm] = useState({
    email: "", name: "", phone: "",
    line1: "", city: "", postal_code: "", province: "", region: "",
    vat_number: "", codice_fiscale: "", company: "", sdi_code: "", pec_address: "",
  });

  useEffect(() => {
    if (items.length === 0) navigate("/prodotti");
  }, [items, navigate]);

  useEffect(() => {
    api.get("/shipping/options").then(({ data }) => setOptions(data));
    api.get("/shipping/regions").then(({ data }) => setRegions(data));
    api.get("/shipping/unloading-service").then(({ data }) => {
      setUnloadingPrice(data.price);
      if (data.label) setUnloadingLabel(data.label);
    });
  }, []);

  useEffect(() => {
    if (user) setForm((f) => ({ ...f, email: f.email || user.email, name: f.name || user.name }));
  }, [user]);

  useEffect(() => {
    if (items.length === 0) return;
    api
      .post("/shipping/quote", {
        items: items.map((i) => ({ product_id: i.product_id, quantity: i.quantity })),
        shipping_option_id: shipId,
        region: form.region || null,
      })
      .then(({ data }) => setQuote(data))
      .catch(() => {});
  }, [shipId, items, form.region]);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const shippingCost = quote.available ? quote.shipping_cost : 0;
  const vatTotal = quote.vat_amount_total || 0;
  const total = subtotal + shippingCost + vatTotal;
  const isAzienda = customerType === "azienda";

  const contactMailto = () => {
    const email = quote.contact_email || "info@ceramicaincontro.it";
    const subject = "Richiesta preventivo spedizione — Ceramica Incontro";
    const itemsList = items.map((i) => `- ${i.name} (Qtà ${i.quantity})`).join("\n");
    const body =
      `Buongiorno,\n\nvorrei un preventivo di spedizione per il mio ordine, ` +
      `non essendo disponibile una tariffa automatica per la mia regione (${form.region || "—"}).\n\n` +
      `Articoli in carrello:\n${itemsList}\n\nPeso totale stimato: ${weight.toFixed(1)} kg\n\n` +
      `Il mio indirizzo di spedizione:\n[Inserisci qui indirizzo, città, CAP, provincia]\n\nGrazie,\n${form.name || ""}`;
    return `mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  const placeOrder = async (e) => {
    e.preventDefault();
    if (!quote.available) {
      toast.error("Spedizione non disponibile per questa regione: contatta il nostro ufficio spedizioni.");
      return;
    }
    if (isAzienda && !form.sdi_code && !form.pec_address) {
      toast.error("Per la fatturazione azienda indica il Codice SDI oppure l'indirizzo PEC.");
      return;
    }
    setBusy(true);
    setError("");
    try {
      const { data } = await api.post("/checkout", {
        items: items.map((i) => ({ product_id: i.product_id, quantity: i.quantity })),
        shipping_option_id: shipId,
        customer: { email: form.email, name: form.name, phone: form.phone },
        shipping_address: {
          line1: form.line1, city: form.city, postal_code: form.postal_code,
          province: form.province, region: form.region, country: "IT",
        },
        billing: isAzienda
          ? {
              is_business: true,
              company: form.company, vat_number: form.vat_number, codice_fiscale: form.codice_fiscale,
              sdi_code: form.sdi_code, pec_address: form.pec_address,
            }
          : { is_business: false },
        payment_method: paymentMethod,
        accept_terms: okTerms,
        accept_withdrawal_info: okWithdrawal,
        origin_url: window.location.origin + "/store",
      });
      clear();
      window.location.href = data.checkout_url;
    } catch (err) {
      setError(formatApiErrorDetail(err.response?.data?.detail) || err.message);
      toast.error("Errore durante il checkout");
      setBusy(false);
    }
  };

  const inputCls = "w-full bg-white border border-[#E2DDD5] px-4 py-3 focus:outline-none focus:border-[#C05A3E] text-sm";

  return (
    <div data-testid="checkout-page" className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <h1 className="font-serif-display text-4xl lg:text-5xl font-light mb-2">Checkout</h1>
      <p className="text-sm text-[#78716C] mb-10">
        {user ? `Ordine come ${user.email}` : "Stai ordinando come ospite. "}
        {!user && <button onClick={() => navigate("/login")} className="text-[#C05A3E] ci-link-underline">Accedi</button>}
      </p>

      {error && <div className="bg-[#FBEAE5] text-[#A64B32] text-sm px-4 py-3 mb-6" data-testid="checkout-error">{error}</div>}

      <form onSubmit={placeOrder} className="grid lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-10" data-testid="checkout-shipping-form">
          {/* Contact */}
          <section>
            <h2 className="eyebrow mb-4 text-[#C05A3E]">1 · Contatti</h2>
            <div className="grid sm:grid-cols-2 gap-4">
              <input className={inputCls} aria-label="Email" placeholder="Email" type="email" required value={form.email} onChange={set("email")} data-testid="checkout-email" />
              <input className={inputCls} aria-label="Nome e cognome" placeholder="Nome e cognome" required value={form.name} onChange={set("name")} data-testid="checkout-name" />
              <input className={inputCls + " sm:col-span-2"} aria-label="Telefono" placeholder="Telefono" value={form.phone} onChange={set("phone")} data-testid="checkout-phone" />
            </div>
          </section>

          {/* Address */}
          <section>
            <h2 className="eyebrow mb-4 text-[#C05A3E]">2 · Indirizzo di spedizione</h2>
            <div className="grid sm:grid-cols-2 gap-4">
              <input className={inputCls + " sm:col-span-2"} aria-label="Indirizzo e civico" placeholder="Indirizzo e civico" required value={form.line1} onChange={set("line1")} data-testid="checkout-line1" />
              <input className={inputCls} aria-label="Città" placeholder="Città" required value={form.city} onChange={set("city")} data-testid="checkout-city" />
              <input className={inputCls} aria-label="CAP" placeholder="CAP" required value={form.postal_code} onChange={set("postal_code")} data-testid="checkout-cap" />
              <input className={inputCls} aria-label="Provincia (es. MO)" placeholder="Provincia (es. MO)" value={form.province} onChange={set("province")} data-testid="checkout-province" />
              <select aria-label="Regione" className={inputCls} required value={form.region} onChange={set("region")} data-testid="checkout-region">
                <option value="">Seleziona regione…</option>
                {regions.map((r) => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
            </div>
          </section>

          {/* Customer type + billing */}
          <section>
            <h2 className="eyebrow mb-4 text-[#C05A3E]">3 · Fatturazione</h2>
            <div className="flex gap-3 mb-4" data-testid="checkout-customer-type">
              <label className={`flex-1 flex items-center gap-2 border p-3 cursor-pointer text-sm ${customerType === "privato" ? "border-[#C05A3E] bg-[#FBF3EF]" : "border-[#E2DDD5] bg-white"}`}>
                <input type="radio" name="customer_type" checked={customerType === "privato"} onChange={() => setCustomerType("privato")} className="accent-[#C05A3E]" data-testid="checkout-customer-privato" />
                Privato
              </label>
              <label className={`flex-1 flex items-center gap-2 border p-3 cursor-pointer text-sm ${customerType === "azienda" ? "border-[#C05A3E] bg-[#FBF3EF]" : "border-[#E2DDD5] bg-white"}`}>
                <input type="radio" name="customer_type" checked={customerType === "azienda"} onChange={() => setCustomerType("azienda")} className="accent-[#C05A3E]" data-testid="checkout-customer-azienda" />
                Azienda
              </label>
            </div>

            {isAzienda && (
              <div className="grid sm:grid-cols-2 gap-4" data-testid="checkout-billing-azienda">
                <input className={inputCls} aria-label="Ragione sociale" placeholder="Ragione sociale" required value={form.company} onChange={set("company")} data-testid="checkout-company" />
                <input className={inputCls} aria-label="Partita IVA" placeholder="Partita IVA" required value={form.vat_number} onChange={set("vat_number")} data-testid="checkout-vat" />
                <input className={inputCls} aria-label="Codice Fiscale" placeholder="Codice Fiscale" value={form.codice_fiscale} onChange={set("codice_fiscale")} data-testid="checkout-cf" />
                <div />
                <input className={inputCls} aria-label="Codice SDI" placeholder="Codice SDI" value={form.sdi_code} onChange={set("sdi_code")} data-testid="checkout-sdi" />
                <input className={inputCls} aria-label="oppure indirizzo PEC" placeholder="oppure indirizzo PEC" type="email" value={form.pec_address} onChange={set("pec_address")} data-testid="checkout-pec" />
                <p className="text-xs text-[#78716C] sm:col-span-2">Indica almeno uno dei due, Codice SDI o PEC, per la fattura elettronica.</p>
              </div>
            )}
          </section>

          {/* Shipping method */}
          <section>
            <h2 className="eyebrow mb-4 text-[#C05A3E]">4 · Metodo di spedizione</h2>
            <div className="space-y-3">
              {options.map((o) => (
                <div key={o.id}>
                  <label
                    data-testid={`shipping-option-${o.id}`}
                    className={`flex items-start gap-4 border p-4 cursor-pointer transition-colors ${
                      shipId === o.id ? "border-[#C05A3E] bg-[#FBF3EF]" : "border-[#E2DDD5] bg-white hover:border-[#C0B9AE]"
                    }`}
                  >
                    <input type="radio" name="ship" checked={shipId === o.id} onChange={() => setShipId(o.id)} className="mt-1 accent-[#C05A3E]" />
                    <div className="flex-1">
                      <div className="flex justify-between">
                        <span className="font-medium text-sm">{o.name}</span>
                        <span className="font-semibold text-sm">
                          {shipId === o.id
                            ? (!form.region ? "—" : quote.available ? (quote.shipping_cost === 0 ? "Gratis" : eur(quote.shipping_cost)) : "N/D")
                            : ""}
                        </span>
                      </div>
                      <p className="text-xs text-[#78716C] mt-0.5">{o.description} · {o.eta}{shipId === o.id && form.region && quote.available && quote.shipping_cost > 0 ? " · iva esclusa" : ""}</p>
                    </div>
                  </label>

                  {o.id === "standard" && shipId === "standard" && (
                    <div className="flex items-start gap-3 border border-[#E2DDD5] bg-[#F8F6F2] p-4 mt-3" data-testid="checkout-unloading-service">
                      <div className="flex-1">
                        <span className="font-medium text-sm">{unloadingLabel}</span>
                        <p className="text-xs text-[#78716C] mt-0.5">
                          Servizio di scarico (sponda idraulica + trans pallet) sempre incluso nel costo di trasporto.
                          La consegna è tassativamente al piano strada.
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>

            {form.region && !quote.available && (
              <div className="mt-4 border border-[#E7C9A8] bg-[#FCF3E6] text-[#8A5A24] text-sm px-4 py-4 space-y-3" data-testid="checkout-shipping-unavailable">
                <p>{quote.message || "Spedizione non disponibile per questa combinazione di regione, peso e categoria. Contatta il nostro ufficio spedizioni."}</p>
                <a
                  href={contactMailto()}
                  className="inline-flex items-center gap-2 bg-[#C05A3E] text-white px-4 py-2 text-xs font-semibold tracking-wide hover:bg-[#A64B32] transition-colors"
                  data-testid="checkout-contact-shipping-btn"
                >
                  <Mail className="w-4 h-4" /> Richiedi preventivo spedizione via email
                </a>
              </div>
            )}
          </section>

          {/* Payment method */}
          <section>
            <h2 className="eyebrow mb-4 text-[#C05A3E]">5 · Metodo di pagamento</h2>
            <div className="space-y-3">
              {cardEnabled && (
                <label
                  data-testid="payment-method-card"
                  className={`flex items-start gap-4 border p-4 cursor-pointer transition-colors ${
                    paymentMethod === "card" ? "border-[#C05A3E] bg-[#FBF3EF]" : "border-[#E2DDD5] bg-white hover:border-[#C0B9AE]"
                  }`}
                >
                  <input type="radio" name="payment" checked={paymentMethod === "card"} onChange={() => setPaymentMethod("card")} className="mt-1 accent-[#C05A3E]" />
                  <div className="flex-1">
                    <span className="font-medium text-sm flex items-center gap-2"><CreditCard className="w-4 h-4" aria-hidden="true" /> Carta di credito / debito</span>
                    <p className="text-xs text-[#78716C] mt-0.5">Pagamento sicuro su Stripe (carte, Apple Pay, Google Pay). I dati della carta non transitano dal nostro sito.</p>
                  </div>
                </label>
              )}
              <label
                data-testid="payment-method-bank_transfer"
                className={`flex items-start gap-4 border p-4 cursor-pointer transition-colors ${
                  paymentMethod === "bank_transfer" ? "border-[#C05A3E] bg-[#FBF3EF]" : "border-[#E2DDD5] bg-white hover:border-[#C0B9AE]"
                }`}
              >
                <input type="radio" name="payment" checked={paymentMethod === "bank_transfer"} onChange={() => setPaymentMethod("bank_transfer")} className="mt-1 accent-[#C05A3E]" />
                <div className="flex-1">
                  <span className="font-medium text-sm">Bonifico bancario</span>
                  <p className="text-xs text-[#78716C] mt-0.5">Riceverai i dati per il bonifico via email dopo l'ordine.</p>
                </div>
              </label>
            </div>
          </section>
        </div>

        {/* Summary */}
        <aside className="lg:col-span-1">
          <div className="bg-white border border-[#E2DDD5] p-6 sticky top-24">
            <h3 className="font-serif-display text-2xl mb-5">Riepilogo</h3>
            <div className="space-y-3 max-h-64 overflow-y-auto no-scrollbar mb-4">
              {items.map((i) => (
                <div key={i.product_id} className="flex gap-3 text-sm">
                  <div className="w-12 h-14 bg-[#F1EEE8] overflow-hidden shrink-0">
                    {i.image && <img src={i.image} alt="" className="w-full h-full object-cover" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="truncate font-medium">{i.name}</p>
                    <p className="text-xs text-[#78716C]">Qtà {i.quantity}</p>
                  </div>
                  <span className="font-medium">{eur(i.price * i.quantity)}</span>
                </div>
              ))}
            </div>
            <div className="border-t border-[#E2DDD5] pt-4 space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-[#78716C]">Subtotale <span className="text-[0.65rem]">(iva esclusa)</span></span><span>{eur(subtotal)}</span></div>
              <div className="flex justify-between">
                <span className="text-[#78716C]">Spedizione <span className="text-[0.65rem]">(iva esclusa, scarico incluso)</span></span>
                <span>{!form.region ? "—" : quote.available ? (shippingCost === 0 ? "Gratis" : eur(shippingCost)) : "N/D"}</span>
              </div>
              <div className="flex justify-between text-xs text-[#78716C]"><span>Peso</span><span>{weight.toFixed(1)} kg</span></div>
              {quote.available && vatTotal > 0 && (
                quote.vat_rate_products === quote.vat_rate_shipping ? (
                  <div className="flex justify-between"><span className="text-[#78716C]">IVA ({quote.vat_rate_products}%)</span><span>{eur(vatTotal)}</span></div>
                ) : (
                  <>
                    <div className="flex justify-between"><span className="text-[#78716C]">IVA prodotti ({quote.vat_rate_products}%)</span><span>{eur(quote.vat_amount_products)}</span></div>
                    <div className="flex justify-between"><span className="text-[#78716C]">IVA trasporto ({quote.vat_rate_shipping}%)</span><span>{eur(quote.vat_amount_shipping)}</span></div>
                  </>
                )
              )}
              <div className="flex justify-between text-lg font-semibold border-t border-[#E2DDD5] pt-3 mt-2">
                <span>Totale</span><span data-testid="checkout-total">{eur(total)}</span>
              </div>
              <p className="text-[0.7rem] text-[#78716C]">IVA inclusa nel totale</p>
            </div>
            <div className="space-y-3 mt-5">
              <ConsentCheckbox checked={okTerms} onChange={setOkTerms} testid="checkout-terms">
                Ho letto e accetto le <Link to="/condizioni-di-vendita" target="_blank" className="underline text-[#A64B32]">Condizioni di vendita</Link> e ho preso visione dell'<Link to="/privacy" target="_blank" className="underline text-[#A64B32]">Informativa privacy</Link>.
              </ConsentCheckbox>
              <ConsentCheckbox checked={okWithdrawal} onChange={setOkWithdrawal} testid="checkout-withdrawal">
                Ho letto le informazioni sul <Link to="/recesso" target="_blank" className="underline text-[#A64B32]">diritto di recesso</Link> (14 giorni, per i consumatori).
              </ConsentCheckbox>
            </div>
            <button
              type="submit"
              data-testid="checkout-place-order-btn"
              disabled={busy || (!!form.region && !quote.available)}
              className="w-full bg-[#C05A3E] text-white py-4 text-sm font-semibold tracking-wide hover:bg-[#A64B32] transition-colors mt-5 disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {busy ? "Invio ordine…" : "Ordine con obbligo di pagamento"}
            </button>
            <div className="flex items-center gap-2 text-xs text-[#78716C] mt-4">
              <ShieldCheck className="w-4 h-4 text-[#6B7A6E]" /> Pagamento tramite bonifico bancario
            </div>
            <div className="flex items-center gap-2 text-xs text-[#78716C] mt-1">
              <Truck className="w-4 h-4 text-[#6B7A6E]" /> Spedizione in tutta Italia
            </div>
          </div>
        </aside>
      </form>
    </div>
  );
}
